import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1187, own='cte_110.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 802 Government and Public Administration Practicum ----
H("802.d.3",3,"A city intern learns that officials must avoid using their positions for personal gain, must disclose conflicts of interest and must treat residents fairly. She is exploring:","government ethics",["traffic engineering","budget printing","park design"],"Ethics guide public service.")
H("802.d.3",4,"A council member's brother bids on a city contract. The most ethical step for the council member is to:","disclose the conflict and step out of the decision",["vote quietly for the bid","hide the relationship","lobby colleagues"],"Disclosure and recusal avoid conflicts.")
H("802.d.1.A",3,"A civics club reads Plato on justice, Aristotle on forms of government and Machiavelli on power to compare early ideas about rule. They are reviewing the works of:","classical political theorists",["modern pop singers","sports coaches","chefs"],"Early theorists shaped political thought.")
H("802.d.1.A",4,"Aristotle is best known in political thought for:","classifying governments and studying their strengths",["inventing paper money","designing the Constitution","writing the Bill of Rights"],"Aristotle compared constitutions.")
H("802.d.1.B",3,"A student traces how Locke's ideas about natural rights and consent of the governed appear in modern democracies. She is analyzing:","contributions of classical theorists to modern political science",["changes in fashion","trends in music","growth of cities"],"Locke influenced modern ideas of rights.")
H("802.d.1.B",4,"The idea that a government's power comes from the consent of the people is most associated with:","Locke",["Machiavelli","Hobbes' absolute monarch alone","a medieval baron"],"Locke argued for consent of the governed.")
H("802.d.2.A",3,"A class reviews the Articles of Confederation, the Constitution's separation of powers and the first ten amendments to see how the founders organized government. They are reviewing:","basic information related to the U.S. Constitution",["state fair rules","school bus routes","sports brackets"],"The Constitution organizes government.")
H("802.d.2.A",4,"The first ten amendments to the U.S. Constitution are called the:","Bill of Rights",["Articles of Confederation","Federalist Papers","Magna Carta"],"The Bill of Rights protects liberties.")
H("802.d.2.B",3,"Students write articles for a classroom government with three branches and a list of student rights, then hold a mock ratification vote. They are creating a:","classroom Constitution and Bill of Rights",["school yearbook","class schedule","lunch menu"],"Simulation builds understanding.")
H("802.d.2.B",4,"A classroom Constitution that divides power between a rules group, an enforcement group and a judging group illustrates:","separation of powers",["a monarchy","a single ruler","anarchy"],"Three branches share power.")
H("802.d.4.A",3,"An intern is asked to look into why a city's permit approvals take so long and whether a new online system is feasible. She begins by researching:","a government and public administration issue",["a movie review","a menu change","a prom theme"],"Research starts with a real problem.")
H("802.d.4.A",4,"A feasibility study asks whether a proposed project is:","practical and workable given time, money and resources",["popular on social media","colorful","short"],"Feasibility tests practicality.")
H("802.d.4.B",3,"After choosing the permit delay issue, the intern interviews staff, reviews the application steps and checks how other cities handle it. She is:","investigating the issues associated with the problem",["ignoring the problem","guessing causes","skipping research"],"Investigate causes before proposing.")
H("802.d.4.B",4,"A good way to find the causes of a long permit process is to:","map each step and note where applications wait",["assume staff are lazy","skip the data","copy another city exactly"],"Process mapping reveals bottlenecks.")
H("802.d.4.C",3,"The intern surveys residents about how long their permit took and observes the counter staff for two mornings. She is collecting:","primary data such as interviews, surveys and observations",["secondary data from a textbook","fiction stories","recipes"],"Primary data comes first-hand.")
H("802.d.4.C",4,"Data an intern gathers herself through a survey is called:","primary data",["secondary data","borrowed data","random data"],"Collected directly.")
H("802.d.4.D",3,"In her report, the intern states the problem, then her method, then findings and recommendations in a clear order. She is:","expressing thoughts logically and sequentially in a formal report",["writing a random list","writing a poem","drawing a map"],"Reports follow a logical order.")
H("802.d.4.D",4,"A formal report usually ends with:","conclusions and recommendations based on the findings",["a joke","a new topic","a random fact"],"Recommendations close a report.")
H("802.d.4.E",3,"The intern turns her survey results into a bar graph showing average wait times by permit type. She is:","interpreting and presenting quantitative data in graph format",["avoiding numbers","writing a story","copying a table"],"Graphs make data clear.")
H("802.d.4.E",4,"A bar graph is most useful for:","comparing amounts across categories",["showing a story","hiding data","listing names"],"Bars compare categories.")
H("802.d.4.F",3,"Before her briefing, the intern prepares slides with key charts and a one-page handout summarizing her recommendations. She is preparing:","visuals and handouts to support the presentation",["a party menu","a travel plan","a game schedule"],"Visuals help the audience follow.")
H("802.d.4.F",4,"A handout is most effective when it:","summarizes the key points on one clear page",["repeats every detail","has tiny print","has no title"],"Concise handouts help.")
H("802.d.4.G",3,"The intern presents her findings and recommendations to the department director and a council member and answers their questions. She is making a:","final presentation of the study to the appropriate stakeholders",["private diary entry","casual chat","social post"],"Stakeholders hear the findings.")
H("802.d.4.G",4,"Stakeholders are people who:","are affected by or have an interest in the outcome",["only work for the city","only own businesses","are all strangers"],"Stakeholders have a stake.")
H("802.d.5.A",3,"A student adds her certificates, a letter of recommendation, a scholarship notice and a sample report to a binder that shows her accomplishments. She is updating a:","professional portfolio with recognitions, awards and scholarships",["scrapbook of jokes","game library","playlist"],"Portfolios collect achievements.")
H("802.d.5.A",4,"A work sample in a portfolio should show:","the quality of the student's own work",["only photos of friends","only a title page","only a list of hobbies"],"Samples demonstrate skill.")
H("802.d.5.B",3,"At the end of her practicum, a student walks a panel of local officials through her portfolio and explains how each piece reflects her skills. She is:","presenting the portfolio to interested stakeholders",["hiding her work","reading a menu","quitting early"],"Share and explain.")
H("802.d.5.B",4,"When presenting a portfolio to officials, a student should:","explain what each piece shows and what she learned",["read every word silently","skip the samples","avoid questions"],"Connect work to skills.")

# ---- 803 Extended Practicum in Government and Public Administration ----
H("803.d.1.A",3,"An intern calls a resident to explain a new recycling rule in short, plain sentences and checks that the resident understood. This is:","clear, concise and accurate verbal communication",["rambling","speaking too fast to follow","using technical jargon only"],"Be clear.")
H("803.d.1.B",3,"After a public meeting, a trainee summarizes the key votes, dates and public comments in a short memo for her supervisor. She is:","analyzing and communicating information, data and observations",["hiding the notes","guessing the votes","skipping the memo"],"Summaries inform decisions.")
H("803.d.1.C",3,"An intern leads a brief team update at the office and later gives a longer slide presentation at a community meeting. She is delivering:","formal and informal presentations",["only written reports","private notes","email only"],"Both informal and formal speaking matter.")
H("803.d.1.C",4,"A formal presentation is usually:","planned with an organized structure and visuals",["spontaneous","unprepared","anonymous"],"Formal means prepared.")
H("803.d.1.D",3,"A trainee at a front counter notices a visitor's furrowed brow and slow speech and offers to repeat the instructions. She is:","observing and interpreting verbal and nonverbal cues",["ignoring the visitor","guessing","rushing"],"Cues show understanding.")
H("803.d.2.A",3,"A team at city hall is asked to reduce wait times at the licensing counter. Each member studies the process independently and then they combine ideas. They are employing:","critical-thinking skills independently and in a team",["avoidance","imitation","chance"],"Critical thinking applies to problems.")
H("803.d.2.A",4,"When tackling a recurring office problem, a team should begin by:","gathering facts about what is actually happening",["assuming the cause","assigning blame","dropping the issue"],"Facts first.")
H("803.d.2.B",3,"A trainee breaks a mailroom backlog into causes such as late pickups and unclear labels, then proposes a new sorting step. She is:","analyzing elements of a problem to develop creative and innovative solutions",["ignoring the causes","denying the backlog","blaming the mail carrier"],"Analyze, then create.")
H("803.d.3.A",3,"A practicum student arrives on time, completes each filing assignment as directed and asks for more work when finished. She is demonstrating:","a positive, productive work ethic",["laziness","entitlement","avoidance"],"Work ethic shows reliability.")
H("803.d.3.A",4,"Which habit best reflects a productive work ethic at a government office?","completing assigned tasks fully and on schedule",["waiting to be reminded","doing the minimum","leaving early"],"Productive effort.")
H("803.d.3.B",3,"A clerk sees that a friend's permit form is incomplete. Showing integrity, she:","asks the friend to complete it like anyone else",["fills it in secretly","approves it anyway","hides it"],"Integrity means fairness.")
H("803.d.3.B",4,"Integrity means choosing the ethical course of action:","even when no one is watching",["only when watched","only for friends","only for rewards"],"Integrity is internal.")
H("803.d.3.C",3,"An intern is tempted to skip a required records check to meet a deadline but follows the rule anyway. She is:","complying with all applicable rules, laws and regulations consistently",["bending rules for speed","ignoring regulations","skipping steps"],"Follow the rules every time.")
H("803.d.4.A",3,"An intern leads a short civic awareness activity at a library, keeps a log of what she did and writes a reflection on its results. She is:","conducting, documenting and evaluating learning activities in a supervised setting",["working without records","ignoring feedback","avoiding supervision"],"Do, document and evaluate.")
H("803.d.4.B",3,"An intern studies whether a city should switch to online forms, comparing costs, time savings and resident needs. She is completing a:","feasibility study",["menu review","game schedule","poetry reading"],"Feasibility tests workability.")
H("803.d.4.B",4,"A product evaluation compares a product's features against:","the needs and standards it is supposed to meet",["its color only","its box design","its brand name only"],"Evaluate against needs.")
H("803.d.4.C",3,"For her study, an intern interviews three department heads, surveys residents and observes a public counter for a day. She is collecting:","primary data",["fiction","rumors","guesses"],"First-hand data.")
H("803.d.4.C",4,"Interviews, surveys and observations are examples of:","primary data collection methods",["secondary sources","opinions only","entertainment"],"They gather original data.")
H("803.d.4.D",3,"An intern calculates the average wait time from her observation data and shows it in a chart for the director. She is:","interpreting and presenting quantitative data",["ignoring numbers","guessing","hiding the results"],"Quantitative data uses numbers.")
H("803.d.4.D",4,"The average of 10, 20 and 30 minutes is:","20 minutes",["10 minutes","30 minutes","60 minutes"],"(10+20+30)/3 = 20.")
H("803.d.4.E",3,"After a mock budget exercise, an intern notes that she is strong at spreadsheets but needs practice explaining numbers aloud. She is:","evaluating strengths and weaknesses in technical skill proficiency",["boasting","hiding results","ignoring feedback"],"Self-evaluation guides growth.")
H("803.d.4.F",3,"At the end of her practicum, a student saves a sample memo, a presentation and a supervisor's evaluation in a folder. She is:","collecting representative work samples",["tossing records","avoiding evidence","copying others' work"],"Work samples show ability.")
H("803.d.4.F",4,"Work samples are useful in a job search because they:","show employers actual examples of your skills",["replace interviews","hide weaknesses","avoid references"],"Samples prove ability.")
H("803.d.4.A",4,"Keeping a learning log during a supervised practicum helps because it:","records activities and reflections that show growth",["replaces supervision","avoids evaluation","hides mistakes"],"Logs document learning.")
H("803.d.4.E",4,"Honest self-evaluation of skill proficiency allows a trainee to:","focus practice on areas that need improvement",["avoid feedback","hide errors","skip training"],"Targeted practice.")
H("803.d.1.A",4,"In a phone call with a resident, the best way to confirm understanding is to:","ask the resident to restate the key steps",["talk faster","hang up politely","change the subject"],"Confirm understanding.")
H("803.d.1.B",4,"A short memo that summarizes a meeting should include:","key decisions, dates and next steps",["jokes","personal opinions only","unrelated stories"],"Memos capture actions.")
H("803.d.1.D",4,"A crossed-arm stance and short answers may signal that a visitor is:","uncomfortable or unconvinced",["very happy","asleep","relaxed"],"Nonverbal cues convey feelings.")
H("803.d.2.B",4,"After identifying the causes of a problem, a team should next:","brainstorm and compare possible solutions",["pick the first idea","cancel the project","ignore the cause"],"Generate options.")
H("803.d.3.C",4,"If a rule seems inconvenient, a public employee should:","follow it and raise concerns through proper channels",["ignore it quietly","break it once","change it alone"],"Follow rules; use channels.")

# ---- 810 Principles of Manufacturing ----
H("810.d.1.A",3,"A student compares a team that designs a new gear with a team that studies the metal's strength, a team that mass-produces the gear and a team that builds the machine's electronics. She is distinguishing among:","engineering, science, manufacturing and technology disciplines",["music, art, drama and dance","history, law, civics and economics","sports, travel, cooking and farming"],"Disciplines have different roles.")
H("810.d.1.A",4,"The discipline most directly focused on turning raw materials into finished products at scale is:","manufacturing",["astronomy","journalism","art history"],"Manufacturing makes products.")
H("810.d.1.B",3,"A shop student uses a calculator to find the area of a steel plate and a computer program to chart defects by day. She is using:","tools such as calculators and computers to solve problems",["only hand guesses","only a pencil","only memory"],"Tools speed accurate solutions.")
H("810.d.1.B",4,"A spreadsheet is most useful in a plant for:","tracking and calculating production data",["drilling holes","welding seams","painting walls"],"Spreadsheets organize data.")
H("810.d.1.C",3,"A technician checks a shaft with a micrometer, a plate with a caliper and a board with a tape measure, choosing each tool for the size and accuracy needed. He is using:","a variety of measuring instruments",["only a stopwatch","only a scale","only a thermometer"],"Different tools suit different measurements.")
H("810.d.1.C",4,"For measuring a very small diameter to a thousandth of an inch, the best tool is a:","micrometer",["yardstick","tape measure","protractor"],"Micrometers are precise.")
H("810.d.2.A",3,"A line lead explains a change to the shift in clear terms, uses standard drawing symbols and confirms everyone understands before starting. She is demonstrating:","communication techniques consistent with industry standards",["rumor-passing","silence","guesses"],"Clear standard communication prevents errors.")
H("810.d.2.A",4,"In manufacturing, a drawing with standardized symbols helps because it:","lets different workers read the same instructions the same way",["makes parts heavier","hides details","replaces tools"],"Standard symbols prevent confusion.")
H("810.d.2.B",3,"When a machine keeps jamming, an operator checks the manual, the maintenance log and the supplier's spec sheet to find the cause. He is:","locating relevant information needed to solve problems",["guessing","ignoring the jam","blaming a coworker"],"Find facts before fixing.")
H("810.d.2.B",4,"The best first source for how to troubleshoot a specific machine is usually its:","operator or maintenance manual",["advertisement","neighbor","random web post"],"Manuals are authoritative.")
H("810.d.2.C",3,"A worker cuts a 96-inch board into equal pieces 12 inches long and then calculates how many pieces fit. He is applying:","mathematics concepts to solve manufacturing problems",["art techniques","dance steps","cooking methods"],"Division finds the count.")
H("810.d.2.C",4,"How many 12-inch pieces can be cut from a 96-inch board, ignoring waste?","8",["6","9","12"],"96 ÷ 12 = 8.")
H("810.d.2.D",3,"Engineers explain that a longer wrench handle makes a stuck bolt easier to turn because it provides a longer lever arm. They are analyzing:","science principles used to solve problems",["fashion trends","sports scores","menu ideas"],"Levers multiply force.")
H("810.d.2.D",4,"A simple machine that makes work easier by reducing the force needed over a longer distance is a:","lever",["thermometer","clock","calculator"],"Levers are simple machines.")
H("810.d.2.E",3,"A technician records the length of a part as 2.5 meters and the mass of a batch as 40 kilograms, not mixing in inches or ounces. He is using:","the appropriate units of measure",["random units","no units","mixed units"],"Consistent units prevent errors.")
H("810.d.2.E",4,"A batch's mass should be recorded in:","kilograms or pounds with the unit written",["inches","gallons","degrees"],"Mass uses mass units.")
H("810.d.3.A",3,"A small team starts a project by defining the goal, then makes a schedule, then builds the product, then checks it and finally reviews the results. They are analyzing the processes needed to complete a project such as:","initiate, plan, execute, monitor and close",["buy, sell, borrow and lend","wake, eat, sleep and play","start, stop, start and stop"],"Project phases.")
H("810.d.3.A",4,"The phase of a project in which the work is actually carried out is called:","execution",["initiation","closure","planning only"],"Execute = do the work.")
H("810.d.3.B",3,"To produce a small wooden toy, students use a saw, a drill and a sander, following the cut list. They are using:","a variety of tools and equipment to produce an item",["no tools","only hands","only paper"],"Choose tools for the task.")
H("810.d.3.B",4,"Before using a power tool in the shop, a student should first:","check that guards are in place and wear eye protection",["remove the guard","skip eye protection","start without checking"],"Safety checks first.")
H("810.d.4.A",3,"Before entering the shop, a student must pass a test on machine guarding, protective gear and hazard reporting based on Occupational Safety and Health Administration rules. She is mastering:","relevant safety tests based on OSHA guidelines and principles",["a spelling test","a music quiz","a geography quiz"],"OSHA sets workplace safety rules.")
H("810.d.4.A",4,"OSHA is the federal agency responsible for:","workplace safety and health standards",["weather reports","postal delivery","college sports"],"OSHA protects workers.")
H("810.d.4.B",3,"A worker reads a Material Safety Data Sheet to learn how to store a solvent, what protective gear to use and how to dispose of it. She is using it to:","analyze, store and safely dispose of hazardous materials",["decorate the shop","order lunch","play a game"],"MSDS describe chemical hazards.")
H("810.d.4.B",4,"A safety data sheet tells a worker:","a chemical's hazards and how to handle it safely",["the price of the chemical","the color of the box","the supplier's logo"],"Safety info first.")
H("810.d.5.A",3,"A technician follows a checklist to lubricate a conveyor, tighten bolts and replace a worn belt. He is performing:","maintenance on selected equipment",["decoration","packaging","marketing"],"Preventive maintenance.")
H("810.d.5.A",4,"Regular lubrication of machine parts mainly helps to:","reduce wear and prevent breakdowns",["increase noise","make parts rust","slow production"],"Lubrication reduces friction.")
H("810.d.5.B",3,"A plant skips oil changes on a press, and the machine seizes and stops production for two days. Students analyze this as the result of:","improper maintenance",["good planning","too much safety","a planned upgrade"],"Neglect causes failure.")
H("810.d.5.B",4,"One likely result of improper maintenance is:","unexpected downtime and higher repair costs",["lower costs","longer machine life","fewer defects"],"Poor maintenance costs more.")
H("810.d.6.A",3,"A plant adds robotic arms to a line that once used hand assembly, which speeds production and changes the skills workers need. Students are analyzing how:","changes in technology affect manufacturing practices",["weather affects crops","music affects mood","sports affect health"],"Technology changes work.")
H("810.d.6.A",4,"One effect of automation on a factory floor is that:","fewer repetitive tasks are done by hand and new technical jobs appear",["no skills are needed","all jobs disappear","machines never break"],"Automation changes jobs.")
H("810.d.6.B",3,"A class studies how the invention of the steam engine, electricity and computers each changed how factories run. They are evaluating how:","technology development is influenced by past events and discoveries",["a poem is rhymed","a game is scored","a menu is written"],"Past innovations build future ones.")
H("810.d.6.B",4,"The assembly line, popularized in the early 1900s, changed manufacturing by:","allowing products to be made faster and more cheaply",["slowing production","ending car making","eliminating factories"],"Assembly line efficiency.")
H("810.d.6.C",3,"A student explains how a product designed in one country can be made in another and shipped around the world, affecting jobs and prices. She is analyzing:","the international effects of technology",["a local bake sale","a school dance","a one-room office"],"Technology links global markets.")
H("810.d.6.C",4,"One international effect of improved shipping and communication technology is:","global supply chains that connect distant producers",["fewer products","isolated factories","no trade"],"Supply chains span countries.")
H("810.d.6.D",3,"Engineers now test new aircraft parts with computer simulations and 3D printers before building them, saving time and money. This demonstrates how advancements in technology have affected:","the field of engineering",["the field of gardening","the field of fashion","the field of sports"],"Technology reshapes engineering.")
H("810.d.6.D",4,"Computer-aided design allows engineers to:","create and test designs digitally before building",["draw only by hand","skip testing","avoid drawings"],"CAD speeds design.")
H("810.d.6.E",3,"A company wants to adopt a new machine, but it costs a lot, requires training and may disrupt output at first. Students are evaluating:","the factors that affect the implementation of new ideas",["lunch plans","parking spaces","room colors"],"Cost, training and disruption matter.")
H("810.d.6.E",4,"A factor that can slow adoption of a new technology in a plant is:","the cost and the time needed for worker training",["a clean floor","a sunny day","a short commute"],"Cost and training are barriers.")
H("810.d.7.A",3,"A student interested in making things researches careers at a local plant, reads job descriptions and talks to a worker. She is:","investigating an area of interest in manufacturing",["watching a movie","skipping class","playing a game"],"Explore interests.")
H("810.d.7.A",4,"A good way to learn what a manufacturing job is really like is to:","job-shadow or interview a worker",["guess","read nothing","avoid the plant"],"Firsthand exposure helps.")
H("810.d.7.B",3,"A chart lists fabrication, machining, assembly, quality control and logistics as separate areas within one plant. Students are analyzing the various:","specializations in manufacturing",["species in a pond","genres in music","positions on a team"],"Plants have many specialties.")
H("810.d.7.B",4,"A specialist who inspects finished parts for defects works in:","quality control",["marketing","payroll","landscaping"],"Quality control checks products.")
H("810.d.7.C",3,"A plant manager explains that the engineer designs the process, the technologist helps put it into practice and the technician maintains the equipment. Students are describing:","the functions of engineers, technologists and technicians",["the jobs of coaches","the roles of chefs","the work of artists"],"Distinct but related roles.")
H("810.d.7.C",4,"Compared with an engineer, a technician typically focuses more on:","installing, operating and maintaining equipment",["inventing new theories","writing laws","teaching classes"],"Technicians work hands-on.")
B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_110.jsonl"))
